import{MethodKind}from"@bufbuild/protobuf";import{Code}from"../code.js";import{codeFromHttpStatus}from"./http-status.js";import{ConnectError}from"../connect-error.js";import{parseContentType}from"./content-type.js";import{headerStreamEncoding,headerUnaryEncoding}from"./headers.js";export function validateResponse(methodKind,status,headers){const mimeType=headers.get("Content-Type"),parsedType=parseContentType(mimeType);if(200!==status){const errorFromStatus=new ConnectError(`HTTP ${status}`,codeFromHttpStatus(status),headers);if(methodKind==MethodKind.Unary&&parsedType&&!parsedType.binary)return{isUnaryError:!0,unaryError:errorFromStatus};throw errorFromStatus}return{isUnaryError:!1}}export function validateResponseWithCompression(methodKind,acceptCompression,status,headers){let compression;const encoding=headers.get(methodKind==MethodKind.Unary?headerUnaryEncoding:headerStreamEncoding);if(null!=encoding&&"identity"!==encoding.toLowerCase()&&(compression=acceptCompression.find(c=>c.name===encoding),!compression))throw new ConnectError(`unsupported response encoding "${encoding}"`,Code.InvalidArgument,headers);return Object.assign({compression},validateResponse(methodKind,status,headers))}