import{CurrencyAmount,Price}from"@uniswap/sdk-core";import{DutchOrder}from"../order";import{areCurrenciesEqual}from"./utils";export class DutchOrderTrade{constructor({currencyIn,currenciesOut,orderInfo,tradeType}){this._currencyIn=currencyIn,this._currenciesOut=currenciesOut,this.tradeType=tradeType,this.order=new DutchOrder(orderInfo,currencyIn.chainId)}get inputAmount(){if(this._inputAmount)return this._inputAmount;const amount=CurrencyAmount.fromRawAmount(this._currencyIn,this.order.info.input.startAmount.toString());return this._inputAmount=amount,amount}get outputAmounts(){if(this._outputAmounts)return this._outputAmounts;const amounts=this.order.info.outputs.map(output=>{const currencyOut=this._currenciesOut.find(currency=>areCurrenciesEqual(currency,output.token,currency.chainId));if(!currencyOut)throw new Error("currency not found in output array");return CurrencyAmount.fromRawAmount(currencyOut,output.startAmount.toString())});return this._outputAmounts=amounts,amounts}getFirstNonFeeOutputStartEndAmounts(){if(this._firstNonFeeOutputStartEndAmounts)return this._firstNonFeeOutputStartEndAmounts;if(0===this.order.info.outputs.length)throw new Error("there must be at least one output token");const output=this.order.info.outputs[0],currencyOut=this._currenciesOut.find(currency=>areCurrenciesEqual(currency,output.token,currency.chainId));if(!currencyOut)throw new Error("currency output from order must exist in currenciesOut list");const startEndAmounts={startAmount:CurrencyAmount.fromRawAmount(currencyOut,output.startAmount.toString()),endAmount:CurrencyAmount.fromRawAmount(currencyOut,output.endAmount.toString())};return this._firstNonFeeOutputStartEndAmounts=startEndAmounts,startEndAmounts}get outputAmount(){return this.getFirstNonFeeOutputStartEndAmounts().startAmount}minimumAmountOut(){return this.getFirstNonFeeOutputStartEndAmounts().endAmount}maximumAmountIn(){return CurrencyAmount.fromRawAmount(this._currencyIn,this.order.info.input.endAmount.toString())}get executionPrice(){var _a;return null!==(_a=this._executionPrice)&&void 0!==_a?_a:this._executionPrice=new Price(this.inputAmount.currency,this.outputAmount.currency,this.inputAmount.quotient,this.outputAmount.quotient)}worstExecutionPrice(){return new Price(this.inputAmount.currency,this.outputAmount.currency,this.maximumAmountIn().quotient,this.minimumAmountOut().quotient)}}