import{getEnsTextQueryOptions}from"@wagmi/core/query";import{useQuery}from"../utils/query.js";import{useChainId}from"./useChainId.js";import{useConfig}from"./useConfig.js";export function useEnsText(parameters={}){const{key,name,query={}}=parameters,config=useConfig(parameters),chainId=useChainId({config}),options=getEnsTextQueryOptions(config,{...parameters,chainId:parameters.chainId??chainId}),enabled=Boolean(key&&name&&(query.enabled??!0));return useQuery({...query,...options,enabled})}