import{getTransactionCount as viem_getTransactionCount}from"viem/actions";import{getAction}from"../utils/getAction.js";export async function getTransactionCount(config,parameters){const{address,blockNumber,blockTag,chainId}=parameters,client=config.getClient({chainId});return getAction(client,viem_getTransactionCount,"getTransactionCount")(blockNumber?{address,blockNumber}:{address,blockTag})}