import{ChainId}from"@uniswap/sdk-core";import{constants}from"ethers";export var NativeAssets;function nativeCurrencyAddressString(chainId){switch(chainId){case ChainId.POLYGON:return NativeAssets.MATIC;case ChainId.BNB:return NativeAssets.BNB;case ChainId.AVALANCHE:return NativeAssets.AVAX;default:return NativeAssets.ETH}}!function(NativeAssets){NativeAssets.MATIC="MATIC",NativeAssets.BNB="BNB",NativeAssets.AVAX="AVAX",NativeAssets.ETH="ETH"}(NativeAssets||(NativeAssets={}));export function areCurrenciesEqual(currency,address,chainId){return currency.chainId===chainId&&(currency.isNative?address===constants.AddressZero||address===nativeCurrencyAddressString(chainId):currency.address.toLowerCase()===(null==address?void 0:address.toLowerCase()))}