import{hexToString}from"viem";import{call,getTransaction,waitForTransactionReceipt as viem_waitForTransactionReceipt}from"viem/actions";import{getAction}from"../utils/getAction.js";export async function waitForTransactionReceipt(config,parameters){const{chainId,timeout=0,...rest}=parameters,client=config.getClient({chainId}),action=getAction(client,viem_waitForTransactionReceipt,"waitForTransactionReceipt"),receipt=await action({...rest,timeout});if("reverted"===receipt.status){const action_getTransaction=getAction(client,getTransaction,"getTransaction"),txn=await action_getTransaction({hash:receipt.transactionHash}),action_call=getAction(client,call,"call"),code=await action_call({...txn,data:txn.input,gasPrice:"eip1559"!==txn.type?txn.gasPrice:void 0,maxFeePerGas:"eip1559"===txn.type?txn.maxFeePerGas:void 0,maxPriorityFeePerGas:"eip1559"===txn.type?txn.maxPriorityFeePerGas:void 0}),reason=code?.data?hexToString(`0x${code.data.substring(138)}`):"unknown reason";throw new Error(reason)}return{...receipt,chainId:client.chain.id}}