import{watchPendingTransactions}from"@wagmi/core";import{useEffect}from"react";import{useChainId}from"./useChainId.js";import{useConfig}from"./useConfig.js";export function useWatchPendingTransactions(parameters={}){const{enabled=!0,onTransactions,config:_,...rest}=parameters,config=useConfig(parameters),configChainId=useChainId({config}),chainId=parameters.chainId??configChainId;useEffect(()=>{if(enabled&&onTransactions)return watchPendingTransactions(config,{...rest,chainId,onTransactions})},[chainId,config,enabled,onTransactions,rest.batch,rest.onError,rest.poll,rest.pollingInterval,rest.syncConnectedChain])}