import{readContractsQueryOptions,structuralSharing}from"@wagmi/core/query";import{useMemo}from"react";import{useQuery}from"../utils/query.js";import{useChainId}from"./useChainId.js";import{useConfig}from"./useConfig.js";export function useReadContracts(parameters={}){const{contracts=[],query={}}=parameters,config=useConfig(parameters),chainId=useChainId({config}),options=readContractsQueryOptions(config,{...parameters,chainId}),enabled=useMemo(()=>{let isContractsValid=!1;for(const contract of contracts){const{abi,address,functionName}=contract;if(!abi||!address||!functionName){isContractsValid=!1;break}isContractsValid=!0}return Boolean(isContractsValid&&(query.enabled??!0))},[contracts,query.enabled]);return useQuery({...options,...query,enabled,structuralSharing:query.structuralSharing??structuralSharing})}