import{watchBlocks as viem_watchBlocks}from"viem/actions";import{getAction}from"../utils/getAction.js";export function watchBlocks(config,parameters){const{syncConnectedChain=config._internal.syncConnectedChain,...rest}=parameters;let unwatch;const listener=chainId=>{unwatch&&unwatch();const client=config.getClient({chainId}),action=getAction(client,viem_watchBlocks,"watchBlocks");return unwatch=action(rest),unwatch},unlisten=listener(parameters.chainId);let unsubscribe;return syncConnectedChain&&!parameters.chainId&&(unsubscribe=config.subscribe(({chainId})=>chainId,async chainId=>listener(chainId))),()=>{unlisten?.(),unsubscribe?.()}}