import{transformEIP1193Provider,validChains}from"@abstract-foundation/agw-client";import{toPrivyWalletConnector}from"@privy-io/cross-app-connect/rainbow-kit";import{}from"@wagmi/core";import{http}from"viem";import{AGW_APP_ID,ICON_URL}from"./constants.js";function abstractWalletConnector(options={}){const{rkDetails,customPaymasterHandler}=options;return params=>{const chains=[...params.chains];let defaultChain=params.chains[0];const validChainIds=Object.keys(validChains).map(Number).sort(function(a,b){return a-b});for(const chainId of validChainIds){const chainIndex=chains.findIndex(chain=>chain.id===chainId);if(-1!==chainIndex){const removedChains=chains.splice(chainIndex,1);defaultChain=removedChains[0]??defaultChain;break}}const connector=toPrivyWalletConnector({iconUrl:ICON_URL,id:AGW_APP_ID,name:"Abstract"})({...params,chains:[defaultChain,...chains]});return{...connector,...rkDetails,getProvider:async parameters=>{const chainId=parameters?.chainId??defaultChain.id;if(!validChains[chainId])throw new Error("Unsupported chain");const chain=params.chains.find(c=>c.id===chainId)??validChains[chainId],provider=await connector.getProvider({chainId}),transport=params.transports?.[chainId]??http(void 0,{batch:!0});return transformEIP1193Provider({provider,chain,transport,isPrivyCrossApp:!0,customPaymasterHandler})},type:"injected",id:"xyz.abs.privy"}}}export{abstractWalletConnector};