import{useMutation}from"@tanstack/react-query";import{signMessageMutationOptions}from"@wagmi/core/query";import{useConfig}from"./useConfig.js";export function useSignMessage(parameters={}){const{mutation}=parameters,config=useConfig(parameters),mutationOptions=signMessageMutationOptions(config),{mutate,mutateAsync,...result}=useMutation({...mutation,...mutationOptions});return{...result,signMessage:mutate,signMessageAsync:mutateAsync}}