export function getAccount(config){const uid=config.state.current,connection=config.state.connections.get(uid),addresses=connection?.accounts,address=addresses?.[0],chain=config.chains.find(chain=>chain.id===connection?.chainId),status=config.state.status;switch(status){case"connected":return{address,addresses,chain,chainId:connection?.chainId,connector:connection?.connector,isConnected:!0,isConnecting:!1,isDisconnected:!1,isReconnecting:!1,status};case"reconnecting":return{address,addresses,chain,chainId:connection?.chainId,connector:connection?.connector,isConnected:!!address,isConnecting:!1,isDisconnected:!1,isReconnecting:!0,status};case"connecting":return{address,addresses,chain,chainId:connection?.chainId,connector:connection?.connector,isConnected:!1,isConnecting:!0,isDisconnected:!1,isReconnecting:!1,status};case"disconnected":return{address:void 0,addresses:void 0,chain:void 0,chainId:void 0,connector:void 0,isConnected:!1,isConnecting:!1,isDisconnected:!0,isReconnecting:!1,status}}}