import{BaseError,toFunctionSelector}from"viem";import{abstract}from"viem/chains";import{decodeAbiParameters,decodeFunctionData}from"viem/utils";import{SessionKeyPolicyRegistryAbi}from"./abis/SessionKeyPolicyRegistry.js";import{SessionKeyValidatorAbi}from"./abis/SessionKeyValidator.js";import{ADD_MODULE_SELECTOR,BATCH_CALL_SELECTOR,CREATE_SESSION_SELECTOR,SESSION_KEY_POLICY_REGISTRY_ADDRESS,SESSION_KEY_VALIDATOR_ADDRESS}from"./constants.js";import{AGWAccountAbi}from"./exports/constants.js";import{ConstraintCondition,getSessionSpec}from"./sessions.js";const restrictedSelectors=new Set([toFunctionSelector("function setApprovalForAll(address, bool)"),toFunctionSelector("function approve(address, uint256)"),toFunctionSelector("function transfer(address, uint256)")]);export var SessionKeyPolicyStatus;!function(SessionKeyPolicyStatus){SessionKeyPolicyStatus[SessionKeyPolicyStatus.Unset=0]="Unset",SessionKeyPolicyStatus[SessionKeyPolicyStatus.Allowed=1]="Allowed",SessionKeyPolicyStatus[SessionKeyPolicyStatus.Denied=2]="Denied"}(SessionKeyPolicyStatus||(SessionKeyPolicyStatus={}));export async function assertSessionKeyPolicies(client,chainId,account,transaction){if(chainId!==abstract.id)return;const sessions=[];if(transaction.to===account.address&&transaction.data?.substring(0,10)===BATCH_CALL_SELECTOR){const batchCall=decodeFunctionData({abi:AGWAccountAbi,data:transaction.data});if("batchCall"===batchCall.functionName)for(const call of batchCall.args[0]){const session=getSessionFromTransaction(account,{...transaction,to:call.target,data:call.callData});session&&sessions.push(session)}}else{const session=getSessionFromTransaction(account,transaction);session&&sessions.push(session)}if(0!==sessions.length)for(const session of sessions){const callPolicies=session.callPolicies,transferPolicies=session.transferPolicies,checks=[];for(const callPolicy of callPolicies)if(restrictedSelectors.has(callPolicy.selector)){const destinationConstraints=callPolicy.constraints.filter(c=>0n===c.index&&c.condition===ConstraintCondition.Equal);if(0===destinationConstraints.length)throw new BaseError(`Unconstrained token approval/transfer destination in call policy. Selector: ${callPolicy.selector}; Target: ${callPolicy.target}`);for(const constraint of destinationConstraints){const[target]=decodeAbiParameters([{type:"address"}],constraint.refValue);checks.push({target,check:{address:SESSION_KEY_POLICY_REGISTRY_ADDRESS,abi:SessionKeyPolicyRegistryAbi,functionName:"getApprovalTargetStatus",args:[callPolicy.target,target]}})}}else checks.push({target:callPolicy.target,check:{address:SESSION_KEY_POLICY_REGISTRY_ADDRESS,abi:SessionKeyPolicyRegistryAbi,functionName:"getCallPolicyStatus",args:[callPolicy.target,callPolicy.selector]}});for(const transferPolicy of transferPolicies)checks.push({target:transferPolicy.target,check:{address:SESSION_KEY_POLICY_REGISTRY_ADDRESS,abi:SessionKeyPolicyRegistryAbi,functionName:"getTransferPolicyStatus",args:[transferPolicy.target]}});const results=await client.multicall({contracts:checks.map(c=>c.check),allowFailure:!1});for(let i=0;i<checks.length;i++){const result=results[i],check=checks[i];if(Number(result)!==SessionKeyPolicyStatus.Allowed)throw new BaseError(`Session key policy violation. Target: ${check?.target}; Status: ${SessionKeyPolicyStatus[Number(result)]}`)}}}function getSessionFromTransaction(account,transaction){if(transaction.to===SESSION_KEY_VALIDATOR_ADDRESS&&transaction.data?.substring(0,10)===CREATE_SESSION_SELECTOR){const sessionSpec=decodeFunctionData({abi:SessionKeyValidatorAbi,data:transaction.data});if("createSession"===sessionSpec.functionName)return sessionSpec.args[0]}if(transaction.to===account?.address&&transaction.data?.substring(0,10)===ADD_MODULE_SELECTOR){const moduleAndData=decodeFunctionData({abi:AGWAccountAbi,data:transaction.data});if("addModule"===moduleAndData.functionName&&moduleAndData.args[0].toLowerCase().startsWith(SESSION_KEY_VALIDATOR_ADDRESS.toLowerCase())){const sessionData=moduleAndData.args[0].substring(42);return decodeAbiParameters([getSessionSpec()],`0x${sessionData}`)[0]}}}