import{useMutation}from"@tanstack/react-query";import{switchAccountMutationOptions}from"@wagmi/core/query";import{useConfig}from"./useConfig.js";import{useConnections}from"./useConnections.js";export function useSwitchAccount(parameters={}){const{mutation}=parameters,config=useConfig(parameters),mutationOptions=switchAccountMutationOptions(config),{mutate,mutateAsync,...result}=useMutation({...mutation,...mutationOptions});return{...result,connectors:useConnections({config}).map(connection=>connection.connector),switchAccount:mutate,switchAccountAsync:mutateAsync}}