import{wait}from"../wait.js";export function withRetry(fn,{delay:delay_=100,retryCount=2,shouldRetry=()=>!0}={}){return new Promise((resolve,reject)=>{const attemptRetry=async({count=0}={})=>{try{const data=await fn();resolve(data)}catch(err){if(count<retryCount&&await shouldRetry({count,error:err}))return(async({error})=>{const delay="function"==typeof delay_?delay_({count,error}):delay_;delay&&await wait(delay),attemptRetry({count:count+1})})({error:err});reject(err)}};attemptRetry()})}