import{watchAsset as viem_watchAsset}from"viem/actions";import{getAction}from"../utils/getAction.js";import{getConnectorClient}from"./getConnectorClient.js";export async function watchAsset(config,parameters){const{connector,...rest}=parameters,client=await getConnectorClient(config,{connector});return getAction(client,viem_watchAsset,"watchAsset")(rest)}