import{getConnectors,watchConnectors}from"@wagmi/core";import{useSyncExternalStore}from"react";import{useConfig}from"./useConfig.js";export function useConnectors(parameters={}){const config=useConfig(parameters);return useSyncExternalStore(onChange=>watchConnectors(config,{onChange}),()=>getConnectors(config),()=>getConnectors(config))}