import{createClient,createPublicClient,createWalletClient,custom,http}from"viem";import{toAccount}from"viem/accounts";import{sessionWalletActions}from"./walletActions.js";export function toSessionClient({client,signer,session,paymasterHandler}){return createSessionClient({account:client.account,chain:client.chain,session,signer,transport:custom(client.transport),paymasterHandler})}export function createSessionClient({account,signer,chain,transport,session,paymasterHandler,nonceManager}){transport||(transport=http(void 0,{batch:!0}));const publicClient=createPublicClient({transport,chain}),parsedAccount="string"==typeof account?toAccount(account):account;nonceManager&&(parsedAccount.nonceManager=nonceManager);const baseClient=createClient({account:parsedAccount,chain,transport}),signerWalletClient=createWalletClient({account:signer,chain,transport});return baseClient.extend(sessionWalletActions(signerWalletClient,publicClient,session,paymasterHandler))}