import{infiniteReadContractsQueryOptions,structuralSharing}from"@wagmi/core/query";import{useInfiniteQuery}from"../utils/query.js";import{useChainId}from"./useChainId.js";import{useConfig}from"./useConfig.js";export function useInfiniteReadContracts(parameters){const{contracts=[],query}=parameters,config=useConfig(parameters),chainId=useChainId({config}),options=infiniteReadContractsQueryOptions(config,{...parameters,chainId,contracts,query});return useInfiniteQuery({...query,...options,initialPageParam:options.initialPageParam,structuralSharing:query.structuralSharing??structuralSharing})}