import{SessionKeyValidatorAbi}from"../abis/SessionKeyValidator.js";import{SESSION_KEY_VALIDATOR_ADDRESS}from"../constants.js";import{getSessionHash,SessionStatus}from"../sessions.js";export async function getSessionStatus(publicClient,address,sessionHashOrConfig){const sessionHash="string"==typeof sessionHashOrConfig?sessionHashOrConfig:getSessionHash(sessionHashOrConfig);return await publicClient.readContract({address:SESSION_KEY_VALIDATOR_ADDRESS,abi:SessionKeyValidatorAbi,functionName:"sessionStatus",args:[address,sessionHash]})}