import{useMutation}from"@tanstack/react-query";import{writeContractMutationOptions}from"@wagmi/core/query";import{useConfig}from"./useConfig.js";export function useWriteContract(parameters={}){const{mutation}=parameters,config=useConfig(parameters),mutationOptions=writeContractMutationOptions(config),{mutate,mutateAsync,...result}=useMutation({...mutation,...mutationOptions});return{...result,writeContract:mutate,writeContractAsync:mutateAsync}}