import{getTransactionCountQueryOptions}from"@wagmi/core/query";import{useQuery}from"../utils/query.js";import{useChainId}from"./useChainId.js";import{useConfig}from"./useConfig.js";export function useTransactionCount(parameters={}){const{address,query={}}=parameters,config=useConfig(parameters),chainId=useChainId({config}),options=getTransactionCountQueryOptions(config,{...parameters,chainId:parameters.chainId??chainId}),enabled=Boolean(address&&(query.enabled??!0));return useQuery({...query,...options,enabled})}