import{ContractFunctionExecutionError}from"viem";import{multicall}from"./multicall.js";import{readContract}from"./readContract.js";export async function readContracts(config,parameters){const{allowFailure=!0,blockNumber,blockTag,...rest}=parameters,contracts=parameters.contracts;try{const contractsByChainId={};for(const[index,contract]of contracts.entries()){const chainId=contract.chainId??config.state.chainId;contractsByChainId[chainId]||(contractsByChainId[chainId]=[]),contractsByChainId[chainId]?.push({contract,index})}const promises=()=>Object.entries(contractsByChainId).map(([chainId,contracts])=>multicall(config,{...rest,allowFailure,blockNumber,blockTag,chainId:Number.parseInt(chainId),contracts:contracts.map(({contract})=>contract)})),multicallResults=(await Promise.all(promises())).flat(),resultIndexes=Object.values(contractsByChainId).flatMap(contracts=>contracts.map(({index})=>index));return multicallResults.reduce((results,result,index)=>(results&&(results[resultIndexes[index]]=result),results),[])}catch(error){if(error instanceof ContractFunctionExecutionError)throw error;const promises=()=>contracts.map(contract=>readContract(config,{...contract,blockNumber,blockTag}));return allowFailure?(await Promise.allSettled(promises())).map(result=>"fulfilled"===result.status?{result:result.value,status:"success"}:{error:result.reason,result:void 0,status:"failure"}):await Promise.all(promises())}}