import{formatUnits}from"viem";import{estimateFeesPerGas as viem_estimateFeesPerGas}from"viem/actions";import{getAction}from"../utils/getAction.js";import{getUnit}from"../utils/getUnit.js";export async function estimateFeesPerGas(config,parameters={}){const{chainId,formatUnits:units="gwei",...rest}=parameters,client=config.getClient({chainId}),action=getAction(client,viem_estimateFeesPerGas,"estimateFeesPerGas"),{gasPrice,maxFeePerGas,maxPriorityFeePerGas}=await action({...rest,chain:client.chain}),unit=getUnit(units);return{formatted:{gasPrice:gasPrice?formatUnits(gasPrice,unit):void 0,maxFeePerGas:maxFeePerGas?formatUnits(maxFeePerGas,unit):void 0,maxPriorityFeePerGas:maxPriorityFeePerGas?formatUnits(maxPriorityFeePerGas,unit):void 0},gasPrice,maxFeePerGas,maxPriorityFeePerGas}}