import{formatUnits,hexToString,trim}from"viem";import{getBalance as viem_getBalance}from"viem/actions";import{getAction}from"../utils/getAction.js";import{getUnit}from"../utils/getUnit.js";import{readContracts}from"./readContracts.js";export async function getBalance(config,parameters){const{address,blockNumber,blockTag,chainId,token:tokenAddress,unit="ether"}=parameters;if(tokenAddress)try{return await getTokenBalance(config,{balanceAddress:address,chainId,symbolType:"string",tokenAddress})}catch(error){if("ContractFunctionExecutionError"===error.name){const balance=await getTokenBalance(config,{balanceAddress:address,chainId,symbolType:"bytes32",tokenAddress}),symbol=hexToString(trim(balance.symbol,{dir:"right"}));return{...balance,symbol}}throw error}const client=config.getClient({chainId}),action=getAction(client,viem_getBalance,"getBalance"),value=await action(blockNumber?{address,blockNumber}:{address,blockTag}),chain=config.chains.find(x=>x.id===chainId)??client.chain;return{decimals:chain.nativeCurrency.decimals,formatted:formatUnits(value,getUnit(unit)),symbol:chain.nativeCurrency.symbol,value}}async function getTokenBalance(config,parameters){const{balanceAddress,chainId,symbolType,tokenAddress,unit}=parameters,contract={abi:[{type:"function",name:"balanceOf",stateMutability:"view",inputs:[{type:"address"}],outputs:[{type:"uint256"}]},{type:"function",name:"decimals",stateMutability:"view",inputs:[],outputs:[{type:"uint8"}]},{type:"function",name:"symbol",stateMutability:"view",inputs:[],outputs:[{type:symbolType}]}],address:tokenAddress},[value,decimals,symbol]=await readContracts(config,{allowFailure:!1,contracts:[{...contract,functionName:"balanceOf",args:[balanceAddress],chainId},{...contract,functionName:"decimals",chainId},{...contract,functionName:"symbol",chainId}]});return{decimals,formatted:formatUnits(value??"0",getUnit(unit??decimals)),symbol,value}}