import{useMutation}from"@tanstack/react-query";import{watchAssetMutationOptions}from"@wagmi/core/query";import{useConfig}from"./useConfig.js";export function useWatchAsset(parameters={}){const{mutation}=parameters,config=useConfig(parameters),mutationOptions=watchAssetMutationOptions(config),{mutate,mutateAsync,...result}=useMutation({...mutation,...mutationOptions});return{...result,watchAsset:mutate,watchAssetAsync:mutateAsync}}